  if(r.policy.itemRates().containsKey("pdc/hearth:trial_enchant")){check(plugin,r.aura.itemRate(item,.05)==.25&&r.aura.itemRate(item,0)==0,"PDC_item_rate_overrides_material_and_cannot_break_zero_loss_worlds");item.editMeta(meta->meta.getPersistentDataContainer().set(new NamespacedKey(plugin,"other_rate"),PersistentDataType.INTEGER,1));boolean ambiguous=false;try{r.aura.itemRate(item,.05);}catch(IllegalStateException conflict){ambiguous=true;}check(plugin,ambiguous,"conflicting_PDC_item_rates_fail_closed_instead_of_iteration_order");item=ItemStack.deserializeBytes(bytes);}var packed=new ItemStack[43];packed[0]=new ItemStack(Material.STONE,60);packed[41]=new ItemStack(Material.STONE,10);packed[42]=item;var result=DeathInventory.pack(packed,41);check(plugin,result[0].getAmount()==64&&result[1].getAmount()==6&&result[2].isSimilar(item)&&packed[0].getAmount()==60,"cursor_and_crafting_inputs_merge_once_without_mutating_before_snapshot");check(plugin,DeathInventory.inputs(org.bukkit.event.inventory.InventoryType.CHEST).length==0&&DeathInventory.inputs(org.bukkit.event.inventory.InventoryType.WORKBENCH).length==9,"shared_container_and_crafting_result_are_excluded_from_personal_death_items");var full=new ItemStack[42];Arrays.fill(full,0,41,new ItemStack(Material.STONE,64));full[41]=item;boolean refused=false;try{DeathInventory.pack(full,41);}catch(IllegalStateException expectedCapacity){refused=true;}check(plugin,refused,"unrepresentable_workspace_overflow_is_HOLD_instead_of_silent_loss");check(plugin,Arrays.stream(org.bukkit.event.entity.PlayerDeathEvent.getHandlerList().getRegisteredListeners()).anyMatch(l->l.getListener()==r.death&&l.getPriority()==org.bukkit.event.EventPriority.LOWEST),"real_Paper_death_listener_is_registered_without_firing_Player_events");check(plugin,kr.toxicity.hud.api.BetterHudAPI.inst().getPlaceholderManager().getStringContainer().getAllPlaceholders().containsKey("hearth_rpg"),"optional_BetterHud_public_cached_placeholder_is_registered");CompletionStage<Void> audit=verifyJournal(plugin,r,new ItemStack[]{item,r.charm(),new ItemStack(Material.STONE,64)});check(plugin,ItemStack.deserializeBytes(bytes).isSimilar(item),"enchant_PDC_and_metadata_survive_native_item_roundtrip");
