   check(plugin,user.getSkillLevel(c.skill())==10&&user.getSkillXp(c.skill())==7&&user.getManaAbilityLevel(c.active())>0&&user.getAbilityLevel(c.passive())>0,"custom_skill_passive_and_active_metadata_loaded"+(phase.equals("resume")?"_from_previous_JVM_YAML":""));for(var extra:r.snapshot().extras())check(plugin,extra.world().toString().equals(saved.getProperty(extra.role())),"same_extra_world_UUID_"+extra.role());
   var house=runtime.housing().snapshot().houses().getFirst();return runtime.housing().target(house.owner(),house.id()).thenComposeAsync(at->{check(plugin,runtime.admission().role(at.getWorld())==Role.PRIVATE_HOME,"existing_owned_house_world_loads_without_recreation");var ctx=runtime.economy().store.context(runtime.economy().settings.realm(),house.owner());if(phase.equals("resume")){check(plugin,r.pvp(at.getWorld())&&r.snapshot().homes().containsKey(house.owner()),"new_Paper_JVM_restores_owner_PvP_and_home_from_PG");return r.refresh().thenRunAsync(()->verifyObject(plugin,r,house.owner(),at.getWorld()),r.owner);}
    var acl=new RpgStore.Acl(UUID.randomUUID(),house.owner(),at.getWorld().getUID(),0,64,0,0,64,0,RpgStore.Mode.LIST,Set.of(id),0);return r.store.object(ctx,acl,-1).thenCompose(v->r.store.pvp(ctx,house.id(),true,-1)).thenCompose(v->r.store.home(ctx,new RpgStore.Home(house.owner(),at.getWorld().getUID(),at.getX(),at.getY(),at.getZ(),0,0,0),-1)).thenComposeAsync(v->r.refresh(),r.owner).thenRunAsync(()->verifyObject(plugin,r,id,at.getWorld()),r.owner);
   },r.owner);
